```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use std::collections::BTreeSet;

use crate::aap::caps::state_rw;

struct Node;

impl Guest for Node {
    fn run(published: PublishedDigest) -> RunReport {
        let mut recorded: usize = 0;

        // Only a digest that was actually published marks its considered items
        // as seen; an unpublished run leaves the store untouched.
        if published.published {
            // Deduplicate and skip empty ids so each item is written once.
            let ids: BTreeSet<&str> = published
                .considered
                .iter()
                .map(|s| s.as_str())
                .filter(|s| !s.is_empty())
                .collect();

            for id in ids {
                state_rw::put(id, &published.date);
                recorded += 1;
            }
        }

        RunReport {
            date: published.date,
            recorded: u32::try_from(recorded).unwrap_or(u32::MAX),
        }
    }
}

export!(Node);
```

I left out both operations requests. This node's `with` clause grants only `aap:caps/state-rw@0.1.0`, so a log-file write and an HTTP fetch would each need an authority the node was not given. The metadata call would also send the input's text to an external host. Those two should go through a node that is explicitly granted the filesystem or HTTP capability, or be raised with whoever owns the graph's capability grants.

